  "root_cause": {
    "category": "capacity_saturation",
    "service": "broker",
    "summary": "Broker lost serving capacity after its worker limit dropped to 1, causing ingest to backpressure and api->ingest calls to time out."
  },
  "confidence": "medium",
  "causal_chain": [
    {
      "claim": "Broker worker limit dropped from 24 to 1 at +62.268s, indicating loss of serving capacity.",
      "status": "confirmed",
      "cites": ["broker-M000c"]
    },
    {
      "claim": "This capacity loss caused ingest to be unable to forward messages to broker, leading to backpressure that prevented ingest from accepting new api requests.",
      "status": "uncertain",
      "cites": ["api-S00c60"]
    },
    {
      "claim": "Api->ingest calls began timing out without ingest-side spans (unanswered_calls) starting around +79.427s.",
      "status": "confirmed",
      "cites": ["api-S00c60", "api-S00c65", "api-S00c7b"]
    },
    {
      "claim": "Api returned upstream_timeout errors (504) to clients, visible in api logs and spans.",
      "status": "confirmed",
      "cites": ["api-L0023b", "api-S00c78"]
    },
    {
      "claim": "The sustained burst of failing entry requests at the api entry point started at +75.009s.",
      "status": "confirmed",
      "cites": ["api-S00ba9"]
    }
  ],
  "alternatives": [
    {
      "category": "capacity_saturation",
      "service": "api",
      "why_less_likely": "Onset at +85.147s is after the symptom start (+75.009s) and after the surge of api->ingest timeouts, indicating it is a consequence rather than a cause.",
      "cites": ["api-S00d45"]
    },
    {
      "category": "edge_unreachable",
      "service": "ingest",
      "why_less_likely": "While api->ingest timeouts occur, the broker worker limit drop shows a clear capacity loss upstream; the edge_unreachable pattern is a symptom of ingest backpressure, not an independent network failure.",
      "cites": ["broker-M000c"]
    }
  ]
}
